//#region index.ts
/** Copies `content` to the clipboard, which can be text, images or an array of these */
async function clippie(content, { reject } = {}) {
	try {
		const items = [content].flat();
		if (navigator?.clipboard?.write) {
			await navigator.clipboard.write([new ClipboardItem(Object.fromEntries(items.map((c) => {
				const type = c.type || "text/plain";
				return [type, new Blob([c], { type })];
			})))]);
			return true;
		}
		return items.every((c) => {
			if (typeof c !== "string") return false;
			const d = document;
			const el = d.createElement("textarea");
			el.value = c;
			el.readOnly = true;
			el.style.cssText = "clip-path:inset(50%);font-size:12pt;white-space:pre";
			el.ariaHidden = "true";
			(d.activeElement?.closest(":modal") ?? d.querySelector(":modal") ?? d.body).append(el);
			try {
				el.select();
				el.setSelectionRange(0, c.length);
				return d.execCommand("copy");
			} finally {
				el.remove();
			}
		});
	} catch (err) {
		if (reject) throw err;
		return false;
	}
}

//#endregion
export { clippie };